The three points $(3,-5)$, $(-a + 2, 3)$, and $(2a+3,2)$ lie on the same line.  What is $a$?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1, y1, x2, y2, x3, y3;
    double slope1, slope2;

    // Read the coordinates of the three points
    cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;

    // Calculate the slopes of the lines passing through the first two points and the second two points
    slope1 = (y2 - y1) / (x2 - x1);
    slope2 = (y3 - y2) / (x3 - x2);

    // Check if the slopes are equal, indicating that the three points lie on the same line
    if (slope1 == slope2) {
        // Calculate the value of a
        double a = (x3 - x2) * (y1 - y2) / (y3 - y2) + x2;

        // Print the value of a
        cout << fixed << setprecision(1) << a << endl;
    } else {
        // Print an error message
        cout << "The three points do not lie on the same line." << endl;
    }

    return 0;
}

