using namespace std;

int main() {
    // Define the polynomial
    vector<pair<int, int>> polynomial = {{1, 1}, {0, -2}, {0, -5}, {0, 6}};

    // Find the roots of the polynomial
    vector<int> roots;
    for (int i = 0; i < polynomial.size(); i++) {
        int root = polynomial[i].second;
        if (root != 0) {
            roots.push_back(root);
        }
    }

    // Find the partial fraction decomposition
    vector<pair<int, int>> partial_fractions;
    for (int i = 0; i < roots.size(); i++) {
        int root = roots[i];
        int numerator = 1;
        int denominator = 1;
        for (int j = 0; j < polynomial.size(); j++) {
            if (polynomial[j].first == root) {
                numerator *= polynomial[j].second;
                denominator *= polynomial[j].second;
            }
        }
        partial_fractions.push_back({numerator, denominator});
    }

    // Find the product of the partial fractions
    int product = 1;
    for (int i = 0; i < partial_fractions.size(); i++) {
        product *= partial_fractions[i].first;
    }

    // Output the result
    cout << "The product of the partial fractions is: " << product << endl;

    return 0;
}

